const input = $json;
const lead = input.lead ?? {};
const email = String(lead.email ?? '').toLowerCase();
const company = String(lead.company ?? '').trim();
const website = String(lead.website ?? '').trim();
const corporateDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
const domain = email.includes('@') ? email.split('@')[1] : '';
const businessEmail = domain && !corporateDomains.includes(domain);
const score = Math.min(100, (businessEmail ? 35 : 15) + (company ? 25 : 0) + (website ? 25 : 0) + (lead.name ? 15 : 0));
return [{ json: {
  run_id: input.idempotency_key,
  lead_id: lead.id,
  score,
  status: 'completed',
  enrichment: {
    email_domain: domain || null,
    is_business_email: businessEmail,
    company_present: Boolean(company),
    website_present: Boolean(website),
    qualification: score >= 75 ? 'hot' : score >= 50 ? 'warm' : 'cold',
    ruleset: 'lead-enrichment-v1'
  },
  verified_at: new Date().toISOString(),
  callback: input.callback
} }];
